static void dm_Dib_put(dm_Dib *d, int64_t k, bool v) {
    uint64_t h = dan_hash_i(k);
    int64_t e = dm_Dib_lookup(d, k, h);
    if (e >= 0) { bool old = d->vals[e]; d->vals[e] = DAN_ID(v); DAN_NOREL(old); (void)old; return; }
    if (d->n == d->cap) dm_Dib_grow(d);
    e = d->n++;
    d->keys[e] = DAN_ID(k); d->vals[e] = DAN_ID(v); d->hashes[e] = h; d->alive[e] = true; d->len++;
    int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));
    while (d->index[p] >= 0) p = (p + 1) & (d->slots - 1);
    d->index[p] = e;
}
